import math
def clamp(x, lo, hi):
    return max(lo, min(hi, x))
def control(obs):
    m = obs.get('local_map', {})
    L, R = m.get('left_rail', []), m.get('right_rail', [])
    def interp(points, u):
        if not points: return None
        pts = sorted(points, key=lambda p: p[0])
        if u <= pts[0][0]: return pts[0][1]
        if u >= pts[-1][0]: return pts[-1][1]
        for a,b in zip(pts, pts[1:]):
            if a[0] <= u <= b[0]:
                f = (u-a[0])/(b[0]-a[0])
                return a[1] + f*(b[1]-a[1])
    centers = []
    for u in (2.0, 4.0, 6.0, 8.0):
        l, r = interp(L,u), interp(R,u)
        if l is not None and r is not None: centers.append((u,(l+r)/2))
    if len(centers) >= 2:
        slope = (centers[-1][1]-centers[0][1])/(centers[-1][0]-centers[0][0])
        err = centers[0][1]
    else: slope, err = 0.0, 0.0
    h = float(obs.get('hitch_deg',0.0))
    steer = clamp(-28.0*slope - 7.0*err + 0.65*h, -22.0, 22.0)
    speed = -0.75
    if abs(h) > 20: speed = -0.45
    if abs(h) > 32: speed = -0.25
    return (steer, speed, 180.0)

