import math
def clamp(x,a,b): return max(a,min(b,x))
def control(obs):
 h=obs.get('hitch_deg',0.0)
 # Pull forward to clear the rail and let the trailer straighten.
 if abs(h)>7:
  steer=clamp(-0.8*h,-24,24)
  return (steer,0.65,180.0)
 # Resume slowly, tracking route bearing and damping hitch.
 route=obs.get('route',{})
 bearing=route.get('bearing_deg',0.0)
 steer=clamp(-0.55*bearing+0.55*h,-18,18)
 return (steer,-0.45,180.0)

