import math
def clamp(x,a,b): return max(a,min(b,x))
def interp(points,u):
    if not points: return None
    pts=sorted(points,key=lambda p:p[0])
    if u<=pts[0][0]: return pts[0][1]
    if u>=pts[-1][0]: return pts[-1][1]
    for a,b in zip(pts,pts[1:]):
        if a[0]<=u<=b[0]:
            f=(u-a[0])/(b[0]-a[0])
            return a[1]+f*(b[1]-a[1])
def control(obs):
    h=obs.get('hitch_deg',0.0)
    m=obs.get('local_map',{})
    L=m.get('left_rail',[])
    R=m.get('right_rail',[])
    vals=[]
    for u in (0.5,1.5,2.5,3.5):
        l=interp(L,u); r=interp(R,u)
        if l is not None and r is not None:
            vals.append((u,(l+r)/2))
    if len(vals)>=2:
        err=vals[0][1]
        slope=(vals[-1][1]-vals[0][1])/(vals[-1][0]-vals[0][0])
