def control(obs):
    # Pull forward gently; centered wheels let the trailer unwind without another sharp sweep.
    if obs.get('status') == 'PULLING_FORWARD':
        return (0.0, 0.4, 180.0)
    # Once clear, make only a cautious reverse attempt guided by the route bearing.
    b = obs.get('route', {}).get('bearing_deg', 0.0)
    h = obs.get('hitch_deg', 0.0)
    steer = max(-10.0, min(10.0, -0.25*b + 0.2*h))
    return (steer, -0.25, 180.0)

