import math
phase = 0
phase_t = 0.0
def control(obs):
    global phase, phase_t
    h = float(obs.get('hitch_deg', 0.0))
    t = float(obs.get('t', 0.0))
    lm = obs.get('local_map', {})
    left = lm.get('left_rail', [])
    right = lm.get('right_rail', [])
    if phase == 0 and abs(h) > 22:
        phase = 1
        phase_t = t
    if phase == 1:
        if abs(h) < 12 and t - phase_t > 5:
            phase = 0
        else:
            return (-18.0 if h > 0 else 18.0, 0.65, 180)
    mids = []
    for u, v in left:
        cand = [(abs(ur-u), vr) for ur, vr in right]
        if cand:
            d, vr = min(cand)
            if d < 0.7 and 4 <= u <= 13:
                mids.append((u, (v+vr)/2.0))
    off = sum(v for u,v in mids)/len(mids) if mids else 0.0
    slope = 0.0
    if len(mids) >= 2:
        um = sum(u for u,v in mids)/len(mids)
        vm = sum(v for u,v in mids)/len(mids)
        den = sum((u-um)**2 for u,v in mids)
        if den:
            slope = sum((u-um)*(v-vm) for u,v in mids)/den
    steer = -5.0*off - 30.0*slope + 0.55*h
    steer = max(-24.0, min(24.0, steer))
    speed = -0.45 if abs(h) > 16 else -0.8
    if abs(slope) > 0.18:
        speed = -0.4
    return (steer, speed, 180)

