def control(obs):
    h = float(obs.get('hitch_deg', 0.0))
    lm = obs.get('local_map', {})
    left = lm.get('left_rail', [])
    right = lm.get('right_rail', [])
    mids = []
    for u, v in left:
        if 1 <= u <= 15 and right:
            ur, vr = min(right, key=lambda p: abs(p[0]-u))
            if abs(ur-u) < 0.8:
                mids.append(((u+ur)/2, (v+vr)/2))
    off = sum(v for u,v in mids)/len(mids) if mids else 0.0
    slope = 0.0
    if len(mids) >= 2:
        um = sum(u for u,v in mids)/len(mids)
        vm = sum(v for u,v in mids)/len(mids)
        den = sum((u-um)**2 for u,v in mids)
        if den:
            slope = sum((u-um)*(v-vm) for u,v in mids)/den
    steer = max(-22.0, min(22.0, -3.0*off - 28.0*slope + 0.45*h))
    speed = -0.45 if abs(h) < 15 else -0.28
    return (steer, speed, 180)

